<script setup lang="ts">
import { ref,onMounted,onUnmounted } from 'vue'
import { api,type VoiceTask } from '../lib/api'
import { japaneseError } from '../../shared/errors.mjs'
const tasks=ref<VoiceTask[]>([]),selected=ref<VoiceTask|null>(null),text=ref(''),error=ref(''),notice=ref(''),busy=ref(false),recording=ref(false),file=ref<File|null>(null),preview=ref('')
const health=ref<Record<string,{ready:boolean;message:string}>>({})
const labels={queued:'排队中',transcribing:'识别中',translating:'转换为日语',completed:'已完成',failed:'失败'}
let timer:ReturnType<typeof setInterval>|undefined,stopTimer:ReturnType<typeof setTimeout>|undefined,recorder:MediaRecorder|undefined,stream:MediaStream|undefined,chunks:BlobPart[]=[],alive=true,dirty=false
async function refresh(){try{const list=await api<VoiceTask[]>('/voice');if(!alive)return;tasks.value=list;if(selected.value&&!dirty){const task=await api<VoiceTask>('/voice/'+selected.value.id);if(alive&&task.id===selected.value?.id){selected.value=task;text.value=task.japanese_text}}}catch(e){if(alive)error.value=japaneseError(e)}}
async function select(id:string){if(dirty&&!window.confirm('放弃尚未保存的修改？'))return;try{const task=await api<VoiceTask>('/voice/'+id);selected.value=task;text.value=task.japanese_text;dirty=false;notice.value=''}catch(e){error.value=japaneseError(e)}}
function setFile(value:File|null){file.value=value;if(preview.value)URL.revokeObjectURL(preview.value);preview.value=value?URL.createObjectURL(value):''}
function choose(event:Event){setFile((event.target as HTMLInputElement).files?.[0]||null)}
async function upload(){if(!file.value)return;error.value='';notice.value='';if(file.value.size>100*1024*1024){error.value='音声ファイルは100 MB以下にしてください。';return}busy.value=true;try{const body=new FormData();body.append('audio',file.value);const task=await api<VoiceTask>('/voice',{method:'POST',body});setFile(null);selected.value=task;text.value='';dirty=false;await refresh()}catch(e){error.value=japaneseError(e)}finally{busy.value=false}}
async function record(){error.value='';try{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw new Error('浏览器不支持录音，请上传音频文件。');const mime=['audio/webm;codecs=opus','audio/webm'].find(t=>MediaRecorder.isTypeSupported(t));if(!mime)throw new Error('浏览器不支持 WebM 录音，请上传 M4A/MP3/WAV 文件。');stream=await navigator.mediaDevices.getUserMedia({audio:true});if(!alive){stream.getTracks().forEach(t=>t.stop());return}chunks=[];recorder=new MediaRecorder(stream,{mimeType:mime});let size=0;recorder.ondataavailable=e=>{if(e.data.size){chunks.push(e.data);size+=e.data.size;if(size>=100*1024*1024&&recorder?.state==='recording')stop()}};recorder.onstop=()=>{stream?.getTracks().forEach(t=>t.stop());if(alive)setFile(new File(chunks,`备忘录-${new Date().toISOString().replace(/[:.]/g,'-')}.webm`,{type:'audio/webm'}));chunks=[]};recorder.start(1000);recording.value=true;stopTimer=setTimeout(stop,1800*1000)}catch(e){stream?.getTracks().forEach(t=>t.stop());error.value=japaneseError(e)}}
function stop(){clearTimeout(stopTimer);if(recorder?.state==='recording')recorder.stop();recording.value=false}
async function action(type:'save'|'retry'|'delete'){if(!selected.value)return;if(type==='delete'&&!window.confirm('删除此备忘录及转写文本？'))return;busy.value=true;error.value='';try{const id=selected.value.id;if(type==='save'){selected.value=await api<VoiceTask>('/voice/'+id,{method:'PATCH',body:JSON.stringify({japanese_text:text.value})});dirty=false;notice.value='已保存'}if(type==='retry'){selected.value=await api<VoiceTask>('/voice/'+id+'/retry',{method:'POST'});dirty=false}if(type==='delete'){await api('/voice/'+id,{method:'DELETE'});selected.value=null;text.value='';dirty=false}await refresh()}catch(e){error.value=japaneseError(e)}finally{busy.value=false}}
async function copy(){try{await navigator.clipboard.writeText(text.value);notice.value='已复制'}catch{error.value='コピーできませんでした。テキストを選択してコピーしてください。'}}
function download(){const url=URL.createObjectURL(new Blob([text.value],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='日语备忘录.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
onMounted(()=>{void refresh();void api<typeof health.value>('/health').then(h=>health.value=h).catch(e=>error.value=japaneseError(e));timer=setInterval(()=>{if(!busy.value)void refresh()},5000)})
onUnmounted(()=>{alive=false;clearInterval(timer);stop();stream?.getTracks().forEach(t=>t.stop());if(preview.value)URL.revokeObjectURL(preview.value)})
</script>
<template><div><div class="page-title"><span class="eyebrow">VOICE MEMO</span><h1>语音备忘录</h1><p>日语对话转成文字，中文部分转换为日语。保留原始转写，方便核对。</p></div>
 <section class="detail-panel"><div class="service-status"><span v-for="(h,key) in health" :key="key" :class="h.ready?'':'error-text'">{{ key==='database'?'数据库':key==='recognition'?'语音识别':'日语翻译' }}：{{ h.ready?'可用':h.message }}</span></div><p class="muted">本机处理，每条最多 30 分钟、100 MB。支持 M4A / MP3 / WAV / WebM；原录音完成后清理，文本保存到你的账号。不自动区分说话人。</p><label>选择音频文件<input type="file" accept=".m4a,.mp3,.wav,.webm" :disabled="busy||recording" @change="choose" /></label><div class="action-row"><button v-if="!recording" class="button" :disabled="busy" @click="record">开始录音</button><button v-else class="button" @click="stop">停止录音</button><button class="button primary" :disabled="!file||busy||recording" @click="upload">{{ busy?'正在处理请求…':'提交录音' }}</button><span v-if="file">{{ file.name }}</span></div><audio v-if="preview" :src="preview" controls /></section>
 <p v-if="error" role="alert" class="error-text">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p><div class="voice-layout"><section class="detail-panel"><h2>最近 100 条备忘录</h2><p v-if="!tasks.length">暂无记录。上传或录制第一条备忘录。</p><button v-for="task in tasks" :key="task.id" class="memo-item" :class="{selected:selected?.id===task.id}" @click="select(task.id)"><strong>{{ task.title }}</strong><span>{{ labels[task.status] }} · {{ task.progress }}% · {{ Math.round(task.duration) }} 秒</span></button></section>
 <section v-if="selected" class="detail-panel"><h2>{{ selected.title }}</h2><p role="status">{{ labels[selected.status] }} {{ selected.progress }}%</p><progress :value="selected.progress" max="100" /><p v-if="selected.error" role="alert" class="error-text">{{ japaneseError(selected.error) }}</p><label>日语结果<textarea v-model="text" lang="ja" rows="14" :readonly="selected.status!=='completed'" @input="dirty=true" /></label><div class="action-row"><button class="button primary" :disabled="busy||selected.status!=='completed'" @click="action('save')">保存修改</button><button class="button" :disabled="!text" @click="copy">复制</button><button class="button" :disabled="!text" @click="download">导出 TXT</button><button v-if="selected.status==='failed'" class="button" :disabled="busy" @click="action('retry')">重试</button><button v-if="['completed','failed'].includes(selected.status)" class="button" :disabled="busy" @click="action('delete')">删除</button></div><details open><summary>原始转写与时间戳</summary><div v-for="(s,i) in selected.segments" :key="i" class="transcript-segment"><time>{{ Math.floor(s.start/60) }}:{{ String(Math.floor(s.start%60)).padStart(2,'0') }}</time><span>{{ s.text }}</span></div><p v-if="!selected.original_text" class="muted">识别完成后显示原始转写。</p></details><p class="muted">结果由机器识别和翻译，请核对专有名词、数字及不清晰的语句。</p></section></div></div></template>
